import sys

MOD = 998244353
GROOT = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(GROOT, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for i in range(0, n, length):
            w = 1
            for j in range(i, i + half):
                u = a[j]
                v = a[j + half] * w % MOD
                a[j] = (u + v) % MOD
                a[j + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def convolution(a, b):
    if not a or not b:
        return []
    if min(len(a), len(b)) <= 60:
        n, m = len(a), len(b)
        res = [0] * (n + m - 1)
        if n < m:
            for i, ai in enumerate(a):
                if ai:
                    for j, bj in enumerate(b):
                        res[i + j] += ai * bj
        else:
            for i, bi in enumerate(b):
                if bi:
                    for j, aj in enumerate(a):
                        res[i + j] += aj * bi
        for i in range(len(res)):
            res[i] %= MOD
        return res

    need = len(a) + len(b) - 1
    n = 1
    while n < need:
        n <<= 1
    fa = a[:] + [0] * (n - len(a))
    fb = b[:] + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]

def poly_inv(a, n):
    # a[0] must be non-zero
    b = [pow(a[0], MOD - 2, MOD)]
    m = 1
    while m < n:
        m2 = min(2 * m, n)
        prod = convolution(a[:m2], b)
        prod = prod[:m2]
        for i in range(m2):
            prod[i] = (-prod[i]) % MOD
        prod[0] = (prod[0] + 2) % MOD
        b = convolution(b, prod)[:m2]
        m = m2
    return b

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    S = input().strip()

    if S[0] != 'B' or S[-1] != 'W':
        print(0)
        return

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # p[t] = number of W before the (t+1)-th B, for t = 1..N-1
    p = [0] * N
    bcnt = 0
    wcnt = 0
    for ch in S:
        if ch == 'B':
            bcnt += 1
            if bcnt > 1:
                p[bcnt - 1] = wcnt
        else:
            wcnt += 1

    us = []
    ss = []
    last_u = -1
    for t in range(1, N):
        u = p[t]
        if u != last_u:
            if t <= u:
                us.append(u)
                ss.append(t)
            last_u = u

    G = len(us)
    if G == 0:
        print(fact[N])
        return

    # Direct O(G^2) for small cases
    if G <= 2000:
        Q = [0] * G
        for i in range(G):
            val = fact[us[i]]
            for j in range(i):
                val -= Q[j] * fact[us[i] - ss[j]]
            Q[i] = (val % MOD) * invfact[us[i] - ss[i]] % MOD
        ans = fact[N]
        for i in range(G):
            ans = (ans - Q[i] * fact[N - ss[i]]) % MOD
        print(ans)
        return

    # Fast path: one contiguous run with constant balance
    one_run = True
    s0 = ss[0]
    u0 = us[0]
    for i in range(G):
        if ss[i] != s0 + i or us[i] != u0 + i:
            one_run = False
            break

    if one_run:
        d = u0 - s0
        F = [fact[u0 + i] for i in range(G)]
        B = [fact[d + i] for i in range(G)]
        invB = poly_inv(B, G)
        Q = convolution(F, invB)[:G]
        ans = fact[N]
        for i in range(G):
            ans = (ans - Q[i] * fact[N - ss[i]]) % MOD
        print(ans)
        return

    # General CDQ divide-and-conquer with NTT
    Q = [0] * G
    E = [0] * G
    sys.setrecursionlimit(1_000_000)

    SMALL = 32
    DIRECT = 20000

    def add_contrib(l, mid, r):
        len_left = mid - l + 1
        len_right = r - mid
        if len_left * len_right <= DIRECT:
            for i in range(mid + 1, r + 1):
                ui = us[i]
                val = 0
                for j in range(l, mid + 1):
                    val += Q[j] * fact[ui - ss[j]]
                E[i] = (E[i] + val) % MOD
            return

        min_s = ss[l]
        max_u = us[r]
        L = max_u - min_s + 1

        # If the NTT would be very large but the left side is tiny, direct is often faster.
        if L > 200000 and len_left < 64:
            for i in range(mid + 1, r + 1):
                ui = us[i]
                val = 0
                for j in range(l, mid + 1):
                    val += Q[j] * fact[ui - ss[j]]
                E[i] = (E[i] + val) % MOD
            return

        A = Q[l:mid + 1]
        B = fact[:L]
        conv = convolution(A, B)
        for i in range(mid + 1, r + 1):
            idx = us[i] - min_s
            if idx < len(conv):
                E[i] = (E[i] + conv[idx]) % MOD

    def cdq(l, r):
        if r - l + 1 <= SMALL:
            for i in range(l, r + 1):
                val = fact[us[i]]
                for j in range(l, i):
                    val -= Q[j] * fact[us[i] - ss[j]]
                Q[i] = (val % MOD) * invfact[us[i] - ss[i]] % MOD
            return

        mid = (l + r) // 2
        cdq(l, mid)
        add_contrib(l, mid, r)
        cdq(mid + 1, r)

    cdq(0, G - 1)

    ans = fact[N]
    for i in range(G):
        ans = (ans - Q[i] * fact[N - ss[i]]) % MOD
    print(ans)

