import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    T = data[idx]
    idx += 1
    out = []
    INF = 10**30

    for _ in range(T):
        N = data[idx]
        K = data[idx + 1]
        idx += 2

        items = []
        for i in range(N):
            x = data[idx]
            y = data[idx + 1]
            z = data[idx + 2]
            idx += 3

            m = x
            if y > m:
                m = y
            if z > m:
                m = z

            # baseline color: any color attaining the maximum
            if x >= y and x >= z:
                b = 0
            elif y >= z:
                b = 1
            else:
                b = 2

            items.append((m, b, x, y, z, i))

        items.sort(key=lambda t: t[0], reverse=True)

        need = 2 * K
        sel = items[:need]
        unsel = items[need:]

        base_total = 0
        parity = 0
        for t in sel:
            base_total += t[0]
            parity ^= 1 << t[1]

        if parity == 0:
            out.append(str(base_total))
            continue

        # Selected items grouped by their baseline color.
        sel_by_base = [[], [], []]
        for t in sel:
            sel_by_base[t[1]].append(t)

        # For unselected items: top two values for each color.
        top1_val = [-1, -1, -1]
        top1_id = [-1, -1, -1]
        top2_val = [-1, -1, -1]
        top2_id = [-1, -1, -1]

        for t in unsel:
            i = t[5]

            val = t[2]
            if val > top1_val[0]:
                top2_val[0], top2_id[0] = top1_val[0], top1_id[0]
                top1_val[0], top1_id[0] = val, i
            elif val > top2_val[0]:
                top2_val[0], top2_id[0] = val, i

            val = t[3]
            if val > top1_val[1]:
                top2_val[1], top2_id[1] = top1_val[1], top1_id[1]
                top1_val[1], top1_id[1] = val, i
            elif val > top2_val[1]:
                top2_val[1], top2_id[1] = val, i

            val = t[4]
            if val > top1_val[2]:
                top2_val[2], top2_id[2] = top1_val[2], top1_id[2]
                top1_val[2], top1_id[2] = val, i
            elif val > top2_val[2]:
                top2_val[2], top2_id[2] = val, i

        max_unsel = [INF, INF, INF]
        for c in range(3):
            if top1_id[c] != -1:
                max_unsel[c] = top1_val[c]

        # max_unsel_sum[c][d] = maximum val_c(j) + val_d(l) over distinct unselected j, l.
        max_unsel_sum = [[INF] * 3 for _ in range(3)]
        for c in range(3):
            for d in range(3):
                if c == d:
                    if top1_id[c] != -1 and top2_id[c] != -1:
                        max_unsel_sum[c][d] = top1_val[c] + top2_val[c]
                else:
                    if top1_id[c] == -1 or top1_id[d] == -1:
                        continue
                    if top1_id[c] != top1_id[d]:
                        max_unsel_sum[c][d] = top1_val[c] + top1_val[d]
                    else:
                        best = -1
                        if top2_id[c] != -1:
                            best = max(best, top2_val[c] + top1_val[d])
                        if top2_id[d] != -1:
                            best = max(best, top1_val[c] + top2_val[d])
                        if best >= 0:
                            max_unsel_sum[c][d] = best

        # Selected item data.
        min_m = [INF] * 3
        min_m_id = [-1] * 3
        min_m2 = [INF] * 3
        min_m2_sum = [INF] * 3

        # min_f[u][v] = min_{selected i with baseline u} (m_i - value_v(i))
        min_f = [[INF] * 3 for _ in range(3)]
        min_f_id = [[-1] * 3 for _ in range(3)]
        min_f2 = [[INF] * 3 for _ in range(3)]
        min_f2_id = [[-1] * 3 for _ in range(3)]

        # H[u][v] = min_{distinct i,k in selected baseline u}
        #           (m_i - value_v(i)) + m_k
        H = [[INF] * 3 for _ in range(3)]

        # RR2[u][a][b] = min_{distinct i,k in selected baseline u}
        #                (m_i - value_a(i)) + (m_k - value_b(k))
        RR2 = [[[INF] * 3 for _ in range(3)] for __ in range(3)]

        for u in range(3):
            L = sel_by_base[u]

            # two smallest m in this baseline color
            m1 = INF
            id1 = -1
            m2 = INF
            id2 = -1
            for t in L:
                m = t[0]
                i = t[5]
                if m < m1:
                    m2, id2 = m1, id1
                    m1, id1 = m, i
                elif m < m2:
                    m2, id2 = m, i

            min_m[u] = m1
            min_m_id[u] = id1
            min_m2[u] = m2
            if id2 != -1:
                min_m2_sum[u] = m1 + m2

            # top two f = m - value_v for each target color v
            for v in range(3):
                if v == u:
                    continue
                f1 = INF
                fid1 = -1
                f2 = INF
                fid2 = -1
                for t in L:
                    m = t[0]
                    i = t[5]
                    f = m - t[2 + v]
                    if f < f1:
                        f2, fid2 = f1, fid1
                        f1, fid1 = f, i
                    elif f < f2:
                        f2, fid2 = f, i

                min_f[u][v] = f1
                min_f_id[u][v] = fid1
                min_f2[u][v] = f2
                min_f2_id[u][v] = fid2

            # H[u][v]
            for v in range(3):
                if v == u:
                    continue
                h = INF
                for t in L:
                    m = t[0]
                    i = t[5]
                    f = m - t[2 + v]
                    best_m = m1 if id1 != i else m2
                    if best_m < INF:
                        cand = f + best_m
                        if cand < h:
                            h = cand
                H[u][v] = h

            # RR2 for the two other colors
            others = [c for c in range(3) if c != u]
            a = others[0]
            b = others[1]

            fb1 = min_f[u][b]
            fb1_id = min_f_id[u][b]
            fb2 = min_f2[u][b]

            rr = INF
            for t in L:
                m = t[0]
                i = t[5]
                fa = m - t[2 + a]
                best_fb = fb1 if fb1_id != i else fb2
                if best_fb < INF:
                    cand = fa + best_fb
                    if cand < rr:
                        rr = cand

            RR2[u][a][b] = rr
            RR2[u][b][a] = rr

        def single_ordered(u, v):
            """Minimum cost of one primitive with parity u xor v."""
            if u == v:
                return INF
            res = min_f[u][v]  # recolor
            if min_m[u] < INF and max_unsel[v] < INF:
                cand = min_m[u] - max_unsel[v]  # swap
                if cand < res:
                    res = cand
            return res

        def min_disjoint_ordered(u, v, p, q):
            """
            Minimum total cost of one primitive u->v and one primitive p->q,
            using disjoint items.
            """
            if u == v or p == q:
                return INF

            res = INF

            # Recolor + Recolor
            if u != p:
                cand = min_f[u][v] + min_f[p][q]
            else:
                if v == q:
                    cand = min_f[u][v] + min_f2[u][v]
                else:
                    cand = RR2[u][v][q]
            if cand < res:
                res = cand

            # Recolor + Swap
            if max_unsel[q] < INF:
                if u != p:
                    if min_f[u][v] < INF and min_m[p] < INF:
                        cand = min_f[u][v] + min_m[p] - max_unsel[q]
                        if cand < res:
                            res = cand
                else:
                    if H[u][v] < INF:
                        cand = H[u][v] - max_unsel[q]
                        if cand < res:
                            res = cand

            # Swap + Recolor
            if max_unsel[v] < INF:
                if u != p:
                    if min_m[u] < INF and min_f[p][q] < INF:
                        cand = min_m[u] + min_f[p][q] - max_unsel[v]
                        if cand < res:
                            res = cand
                else:
                    if H[u][q] < INF:
                        cand = H[u][q] - max_unsel[v]
                        if cand < res:
                            res = cand

            # Swap + Swap
            if u != p:
                sel_sum = min_m[u] + min_m[p]
            else:
                sel_sum = min_m2_sum[u]

            unsel_sum = max_unsel_sum[v][q]
            if sel_sum < INF and unsel_sum < INF:
                cand = sel_sum - unsel_sum
                if cand < res:
                    res = cand

            return res

        # parity has exactly two bits set
        if parity == 3:       # colors 0 and 1
            a, b, c = 0, 1, 2
        elif parity == 5:     # colors 0 and 2
            a, b, c = 0, 2, 1
        else:                 # parity == 6, colors 1 and 2
            a, b, c = 1, 2, 0

        # Fix parity with one primitive.
        best_fix = min(single_ordered(a, b), single_ordered(b, a))

        # Fix parity with two primitives: the other two pair types.
        two = INF
        for u, v in ((a, c), (c, a)):
            for p, q in ((b, c), (c, b)):
                cand = min_disjoint_ordered(u, v, p, q)
                if cand < two:
                    two = cand

        if two < best_fix:
            best_fix = two

        out.append(str(base_total - best_fix))

    sys.stdout.write("\n".join(out))


