from typing import List
from collections import deque

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        pref_num = [0] * (n + 1)
        pref_cost = [0] * (n + 1)
        for i in range(n):
            pref_num[i + 1] = pref_num[i] + nums[i]
            pref_cost[i + 1] = pref_cost[i] + cost[i]

        INF = 10 ** 30
        dp_prev = [INF] * (n + 1)
        dp_prev[0] = 0
        ans = INF

        for seg in range(1, n + 1):
            dp_cur = [INF] * (n + 1)
            hull = deque()
            km = k * seg

            for i in range(seg, n + 1):
                p = i - 1
                if dp_prev[p] < INF:
                    slope = -pref_cost[p]
                    intercept = dp_prev[p]

                    while len(hull) >= 2:
                        s1, b1 = hull[-2]
                        s2, b2 = hull[-1]
                        if (b2 - b1) * (s2 - slope) >= (intercept - b2) * (s1 - s2):
                            hull.pop()
                        else:
                            break
                    hull.append((slope, intercept))

                if not hull:
                    continue

                x = pref_num[i] + km
                while len(hull) >= 2:
                    s1, b1 = hull[0]
                    s2, b2 = hull[1]
                    if s1 * x + b1 >= s2 * x + b2:
                        hull.popleft()
                    else:
                        break

                s, b = hull[0]
                dp_cur[i] = s * x + b + x * pref_cost[i]

            if dp_cur[n] < ans:
                ans = dp_cur[n]
            dp_prev = dp_cur

        return ans

