import sys

def h_detour(x, y, m, side):
    pts = []
    for i in range(m + 1):
        pts.append((x, y + side * i))
    for i in range(m + 1):
        pts.append((x + 1, y + side * (m - i)))
    return pts

def axis_path_d1(L, side):
    m = (L - 1) // 2
    return h_detour(0, 0, m, side)

def axis_path_d2(L, side):
    m = L // 2 - 1
    pts = h_detour(0, 0, m, side)
    pts.append((2, 0))
    return pts

def diag_path_11(L):
    m = L // 2 - 1
    pts = h_detour(0, 0, m, -1)
    pts.append((1, 1))
    return pts

def axis_cycle(L):
    M = L // 2
    pts = []
    for x in range(M):
        pts.append((x, 0))
    pts.append((M - 1, 1))
    for x in range(M - 2, -1, -1):
        pts.append((x, 1))
    return pts

def inv(u, v):
    return (u + v, u - v)

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out = []
    SHIFT = 10**6
    for _ in range(t):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2
        if R + B < 2:
            out.append("No")
            continue
        if R % 2 == 1 or (R == 0 and B % 2 == 1):
            out.append("No")
            continue
        out.append("Yes")
        if B == 0:
            for x, y in axis_cycle(R):
                out.append(f"R {x + SHIFT} {y + SHIFT}")
        elif R == 0:
            for u, v in axis_cycle(B):
                x, y = inv(u, v)
                out.append(f"B {x + SHIFT} {y + SHIFT}")
        else:
            if B % 2 == 0:
                red_pts = axis_path_d2(R, 1)
                for i in range(R):
                    x, y = red_pts[i]
                    out.append(f"R {x + SHIFT} {y + SHIFT}")
                blue_pts = diag_path_11(B)
                for i in range(B):
                    u, v = blue_pts[i]
                    qu = 1 - u
                    qv = 1 - v
                    x, y = inv(qu, qv)
                    out.append(f"B {x + SHIFT} {y + SHIFT}")
            else:
                red_pts = diag_path_11(R)
                for i in range(R):
                    x, y = red_pts[i]
                    out.append(f"R {x + SHIFT} {y + SHIFT}")
                blue_pts = axis_path_d1(B, 1)
                for i in range(B):
                    u, v = blue_pts[i]
                    qu = 1 - u
                    qv = -v
                    x, y = inv(qu, qv)
                    out.append(f"B {x + SHIFT} {y + SHIFT}")
    sys.stdout.write("\n".join(out))

