import sys
from collections import deque

def solve() -> None:
    input = sys.stdin.readline
    N, M = map(int, input().split())
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N
    isolated = 0
    odd_non_isolated = 0
    even_odd_odd = 0
    ab_parity = 0

    for s in range(N):
        if color[s] != -1:
            continue

        if not adj[s]:
            isolated += 1
            color[s] = 0
            continue

        cnt = [0, 0]
        q = deque([s])
        color[s] = 0
        while q:
            v = q.popleft()
            cnt[color[v]] += 1
            for to in adj[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    q.append(to)

        a, b = cnt
        size = a + b
        ab_parity ^= (a & 1) & (b & 1)

        if size == 1:
            isolated += 1
        elif size & 1:
            odd_non_isolated += 1
        else:
            if (a & 1) and (b & 1):
                even_odd_odd += 1

    missing_parity = (ab_parity ^ (M & 1)) & 1

    if N & 1:
        win = (M & 1) == 1
    else:
        o = odd_non_isolated
        i = isolated
        e1 = even_odd_odd
        m = missing_parity

        if o % 4 in (1, 2):
            win = True
        elif o == 0:
            # P-position iff m == (i // 2) % 2
            win = (m != ((i // 2) & 1))
        elif o % 4 == 3:
            # P-position iff i is odd, m == (i // 2) % 2, and e1 is even
            if (i & 1) and (m == ((i // 2) & 1)) and ((e1 & 1) == 0):
                win = False
            else:
                win = True
        else:  # o % 4 == 0 and o > 0
            # P-position iff i == 0, m == 0, and e1 is even
            if i == 0 and m == 0 and ((e1 & 1) == 0):
                win = False
            else:
                win = True

    print("Aoki" if win else "Takahashi")

