class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        edges_by_left = [[] for _ in range(n + 1)]

        for i, (x, y) in enumerate(conflictingPairs):
            if x < y:
                a, b = x, y
            else:
                a, b = y, x
            edges_by_left[a].append((b, i))

        INF = n + 1

        min1 = INF
        count_min1 = 0
        id_min1 = -1
        min2 = INF

        base = 0
        gain = [0] * m

        for left in range(n, 0, -1):
            for right, idx in edges_by_left[left]:
                if right < min1:
                    min2 = min1
                    min1 = right
                    count_min1 = 1
                    id_min1 = idx
                elif right == min1:
                    count_min1 += 1
                    id_min1 = -1
                else:
                    if right < min2:
                        min2 = right

            base += min1 - left

            if count_min1 == 1:
                gain[id_min1] += min2 - min1

        return base + max(gain)

