    C = [[0] * (W + 1) for _ in range(W + 1)]
    for i in range(W + 1):
        C[i][0] = 1
        C[i][i] = 1
        for j in range(1, i):
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j]

    f = [min(k, W - k) for k in range(W + 1)]
    B = [0] * (W + 1)

    for t in range(W + 1):
        total = 0
        row_t = C[t]
        row_rest = C[W - t]
        rest_len = W - t + 1
        for j in range(t + 1):
            cj = row_t[j]
            if j & 1:
                for l in range(rest_len):
                    total -= cj * row_rest[l] * f[j + l]
            else:
                for l in range(rest_len):
                    total += cj * row_rest[l] * f[j + l]
        B[t] = total

    fwht(a)

    bc = int.bit_count
    B_local = B
    for i in range(N):
        a[i] *= B_local[bc(i)]

    fwht(a)

    print(min(a) // N)


