class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        A = ord('a')

        p = [ord(c) for c in str2]

        # Prefix function for KMP.
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and p[i] != p[j]:
                j = pi[j - 1]
            if p[i] == p[j]:
                j += 1
            pi[i] = j

        pi_last = pi[m - 1]
        m_minus_1 = m - 1

        # KMP automaton: next_state[q][c] = state after reading char c from state q.
        next_state = [[0] * 26 for _ in range(m)]
        for q in range(m):
            ns = next_state[q]
            pq = p[q]
            fb = next_state[pi[q - 1]] if q > 0 else None
            for ci in range(26):
                c = A + ci
                if pq == c:
                    k = q + 1
                elif q == 0:
                    k = 0
                else:
                    k = fb[ci]
                ns[ci] = pi_last if k == m else k

        last_ci = p[-1] - A
        last_char = str2[-1]

        bits = [1 << i for i in range(m)]
        all_states = (1 << m) - 1
        bit_last = bits[m_minus_1]

        # pre0[q]: next states reachable from q by any char.
        # pre2[q]: next states reachable from q by a char that does NOT complete str2.
        pre0 = [0] * m
        pre2 = [0] * m
        for q in range(m):
            all_bits = 0
            for_bits = 0
            ns = next_state[q]
            for ci in range(26):
                b = bits[ns[ci]]
                all_bits |= b
                # A full match can only happen from state m-1 using str2[-1].
                if not (q == m_minus_1 and ci == last_ci):
                    for_bits |= b
            pre0[q] = all_bits
            pre2[q] = for_bits

        # Constraint type at each ending position:
        # 0 = no constraint, 1 = must match, 2 = must not match.
        types = [0] * L
        for i, ch in enumerate(str1):
            types[i + m - 1] = 1 if ch == 'T' else 2

        # dp[t] is a bitset of KMP states from which a valid suffix starting at t exists.
        dp = [0] * (L + 1)
        dp[L] = all_states
        range_m = range(m)

        for t in range(L - 1, -1, -1):
            typ = types[t]
            nxt = dp[t + 1]

            if typ == 1:
                # Only state m-1 can match, and it must go to pi_last.
                cur = bit_last if (nxt & bits[pi_last]) else 0
            else:
                # If every next state is feasible, every current state is feasible
                # for no-constraint or forbid-constraint positions.
                if nxt == all_states:
                    cur = all_states
                else:
                    arr = pre0 if typ == 0 else pre2
                    cur = 0
                    for q in range_m:
                        if arr[q] & nxt:
                            cur |= bits[q]
                            if cur == all_states:
                                break

            dp[t] = cur
            if cur == 0:
                return ""

        if (dp[0] & 1) == 0:
            return ""

        letters = [chr(A + i) for i in range(26)]
        ans = []
        state = 0

        # Greedily construct the lexicographically smallest valid string.
        for t in range(L):
            typ = types[t]
            nxt_dp = dp[t + 1]

            if typ == 1:
                if state == m_minus_1 and (nxt_dp & bits[pi_last]):
                    ans.append(last_char)
                    state = pi_last
                else:
                    return ""
            else:
                ns = next_state[state]
                chosen = False

                if typ == 2:
                    for ci in range(26):
                        if state == m_minus_1 and ci == last_ci:
                            continue
                        if nxt_dp & bits[ns[ci]]:
                            ans.append(letters[ci])
                            state = ns[ci]
                            chosen = True
                            break
                else:
                    for ci in range(26):
                        if nxt_dp & bits[ns[ci]]:
                            ans.append(letters[ci])
                            state = ns[ci]
                            chosen = True
                            break

                if not chosen:
                    return ""

        return ''.join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        LIMIT = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def count_completions(rem_odd: int, rem_even: int, length: int, next_parity: int) -> int:
            if next_parity == 1:
                need_odd = (length + 1) // 2
                need_even = length // 2
            else:
                need_odd = length // 2
                need_even = (length + 1) // 2

            if need_odd != rem_odd or need_even != rem_even:
                return 0

            prod = fact[rem_odd] * fact[rem_even]
            return LIMIT if prod > LIMIT else prod

        rem_odd = (n + 1) // 2
        rem_even = n // 2
        used = [False] * (n + 1)
        ans = []

        for pos in range(n):
            required_parity = None
            if pos > 0:
                required_parity = 1 - (ans[-1] % 2)

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x % 2
                if required_parity is not None and parity != required_parity:
                    continue

                new_odd = rem_odd - (1 if parity == 1 else 0)
                new_even = rem_even - (1 if parity == 0 else 0)

                cnt = count_completions(
                    new_odd,
                    new_even,
                    n - pos - 1,
                    1 - parity
                )

                if cnt >= k:
                    ans.append(x)
                    used[x] = True
                    rem_odd = new_odd
                    rem_even = new_even
                    break

                k -= cnt
            else:
                return []

        return ans

