MOD = 998244353


def build_coeff():
    # Relation masks for one position.
    # bit (u<<1)|v means a_{i-1}=u can go to a_i=v.
    # s=0: d=0,1,2
    R0 = (2, 9, 4)
    # s=1: d=0,1,2,3
    R1 = (2, 11, 13, 4)

    # compose[M][R] = M o R
    comp = [[0] * 16 for _ in range(16)]
    for m in range(16):
        for r in range(16):
            res = 0
            for u in range(2):
                for v in range(2):
                    if (m >> ((u << 1) | v)) & 1:
                        for w in range(2):
                            if (r >> ((v << 1) | w)) & 1:
                                res |= 1 << ((u << 1) | w)
            comp[m][r] = res

    # coeff[s][next_state] = list of (prev_state, multiplicity)
    # State 0 (empty relation) is dead and is omitted.
    coeff = [[[] for _ in range(16)] for _ in range(2)]
    for si, Rlist in enumerate((R0, R1)):
        for m in range(1, 16):
            cnt = [0] * 16
            for r in Rlist:
                n = comp[m][r]
                if n:
                    cnt[n] += 1
            for n in range(1, 16):
                if cnt[n]:
                    coeff[si][n].append((m, cnt[n]))
    return coeff


def make_process(coeff):
    def expr(terms):
        if not terms:
            return "0"
        parts = []
        for m, c in terms:
            if c == 1:
                parts.append(f"d{m}")
            else:
                parts.append(f"d{m}*{c}")
        return " + ".join(parts)

    lines = []
    params = ", ".join(f"d{i}" for i in range(1, 16))
    lines.append(f"def process(s, {params}):")
    lines.append("    mod = 998244353")
    lines.append("    i = 0")
    lines.append("    for ch in s:")
    lines.append("        if ch == 48:")
    for n in range(1, 16):
        lines.append(f"            n{n} = {expr(coeff[0][n])}")
    for n in range(1, 16):
        lines.append(f"            d{n} = n{n}")
    lines.append("        else:")
    for n in range(1, 16):
        lines.append(f"            n{n} = {expr(coeff[1][n])}")
    for n in range(1, 16):
        lines.append(f"            d{n} = n{n}")
    lines.append("        if (i & 15) == 15:")
    for n in range(1, 16):
        lines.append(f"            d{n} %= mod")
    lines.append("        i += 1")
    ret = ", ".join(f"d{i} % mod" for i in range(1, 16))
    lines.append(f"    return {ret}")

    code = "\n".join(lines)
    ns = {}
    exec(code, ns)
    return ns["process"]


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    s = data[1]

    coeff = build_coeff()
    process = make_process(coeff)

    # Initial relation: identity on {0,1}, mask = (0,0) and (1,1) = 9.
    dp = [0] * 16
    dp[9] = 1

    res = process(s, *dp[1:])

    ans = 0
    for m in range(1, 16):
        if m & 9:  # has (0,0) or (1,1)
            ans += res[m - 1]

    print(ans % MOD)


