import sys

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    T = int(next(it))
    out = []

    for _ in range(T):
        N = int(next(it))
        A = next(it).decode()
        B = next(it).decode()

        P = [i + 1 for i, c in enumerate(A) if c == '1']
        Q = [i + 1 for i, c in enumerate(B) if c == '1']
        m = len(P)
        n = len(Q)

        if m < n:
            out.append("-1")
            continue

        if P[-1] - P[0] < Q[-1] - Q[0]:
            out.append("-1")
            continue

        if A == B:
            out.append("0")
            continue

        if n == 1:
            q = Q[0]
            ans = max(abs(q - P[0]), abs(q - P[-1]))
            out.append(str(ans))
            continue

        gaps = [P[i + 1] - P[i] for i in range(m - 1)]
        tgaps = [Q[i + 1] - Q[i] for i in range(n - 1)]

        def feasible(K):
            if P[0] < Q[0] - K:
                return False
            if P[-1] > Q[-1] + K:
                return False

            # l = first index with P[l] >= Q[1] - K
            l = 0
            while l < m and P[l] < Q[1] - K:
                l += 1
            release = l - 1
            if release < 0:
                release = -1

            # r = first index with P[r] > Q[0] + K
            r = 0
            while r < m and P[r] <= Q[0] + K:
                r += 1
            deadline = r - 1
            max_b = m - n
            if deadline > max_b:
                deadline = max_b

            if release > deadline:
                return False

            j = 0
            # Try to choose cuts for target gaps 0..n-2
            for b in range(m - 1):
                if b < release:
                    continue
                if b > deadline:
                    return False

                if gaps[b] >= tgaps[j]:
                    j += 1
                    if j == n - 1:
                        break

                    # update release for next target gap: block j+1 left bound
                    while l < m and P[l] < Q[j + 1] - K:
                        l += 1
                    release = l - 1
                    if release < 0:
                        release = -1

                    # update deadline for next target gap: block j right bound
                    while r < m and P[r] <= Q[j] + K:
                        r += 1
                    deadline = r - 1
                    max_b = m - n + j
                    if deadline > max_b:
                        deadline = max_b

                    if release > deadline:
                        return False

            return j == n - 1

        if not feasible(N):
            out.append("-1")
            continue

        lo, hi = 0, N
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        out.append(str(lo))

    sys.stdout.write("\n".join(out))

