class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        C = 4 * s
        per = []
        for x, y in points:
            if y == 0:
                per.append(x)
            elif x == s:
                per.append(s + y)
            elif y == s:
                per.append(3 * s - x)
            else:
                per.append(4 * s - y)
        per.sort()
        n = len(per)
        p3 = per + [v + C for v in per] + [v + 2 * C for v in per]
        nxt = [0] * (2 * n)
        m_range = range(2 * n)
        start_range = range(n)
        jump_range = range(k - 1)
        def feasible(D: int, arr=p3, n_local=n, m_range=m_range, start_range=start_range,
                     jump_range=jump_range, nxt=nxt, C_local=C, k_local=k) -> bool:
            if D == 0:
                return True
            if k_local * D > C_local:
                return False
            j = 0
            for i in m_range:
                if j <= i:
                    j = i + 1
                target = arr[i] + D
                limit = i + n_local
                while j < limit and arr[j] < target:
                    j += 1
                nxt[i] = j
            max_diff = C_local - D
            for i in start_range:
                idx = i
                limit = i + n_local
                for _ in jump_range:
                    idx = nxt[idx]
                    if idx >= limit:
                        break
                else:
                    if arr[idx] - arr[i] <= max_diff:
                        return True
            return False
        lo = 0
        hi = C // k
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

