MOD = 998244353
MAXA = 1000

spf = list(range(MAXA + 1))
if MAXA >= 1:
    spf[1] = 1
for i in range(2, isqrt(MAXA) + 1):
    if spf[i] == i:
        for j in range(i * i, MAXA + 1, i):
            if spf[j] == j:
                spf[j] = i

factors = [[] for _ in range(MAXA + 1)]
for x in range(2, MAXA + 1):
    y = x
    while y > 1:
        p = spf[y]
        e = 0
        while y > 1 and spf[y] == p:
            y //= p
            e += 1
        factors[x].append((p, e))


def update_one(F, B, a, H, pp, mod):
    new = [0] * (H + 1)
    if B <= 0:
        return new

    ha = H - a

    end = B
    t = a - 1
    if t < end:
        end = t
    if ha < end:
        end = ha
    for k in range(1, end + 1):
        v = F[k + a]
        if v:
            new[k] = (v * pp[k]) % mod

    end = B
    if ha < end:
        end = ha
    if a <= end:
        for k in range(a, end + 1):
            v = F[k - a] + F[k + a]
            if v:
                new[k] = (v * pp[k]) % mod

    start = a
    t = ha + 1
    if t > start:
        start = t
    if start <= B:
        for k in range(start, B + 1):
            v = F[k - a]
            if v:
                new[k] = (v * pp[k]) % mod

    return new


def calc(base, arr, H):
    mod = MOD
    pp = [1] * (H + 1)
    for i in range(1, H + 1):
        pp[i] = (pp[i - 1] * base) % mod

    dp0 = [0] * (H + 1)
    dp1 = [0] * (H + 1)
    dp1[0] = 1
    if H:
        dp0[1:] = pp[1:]

    pref = 0
    upd = update_one

    for a in arr:
        if a == 0:
            B1 = pref
            B0 = H - pref
            for k in range(1, B0 + 1):
                v = dp0[k]
                if v:
                    dp0[k] = (v * pp[k]) % mod
            for k in range(1, B1 + 1):
                v = dp1[k]
                if v:
                    dp1[k] = (v * pp[k]) % mod
        else:
            pref += a
            B1 = pref
            B0 = H - pref

            new0 = upd(dp0, B0, a, H, pp, mod)
            new1 = upd(dp1, B1, a, H, pp, mod)
            new1[0] = (dp1[a] + dp0[a]) % mod

            dp0, dp1 = new0, new1

    return sum(dp1) % mod


