    Gs = {}

    for i, val in enumerate(A):
        for p, e in factors[val]:
            arr = prime_arrays.get(p)
            if arr is None:
                arr = [0] * M
                prime_arrays[p] = arr
                Gs[p] = 0
            arr[i] = e
            Gs[p] = gcd(Gs[p], e)

    ans = 1
    for p, arr in prime_arrays.items():
        g = Gs[p]
        if g == 0:
            continue

        if g > 1:
            arr = [a // g for a in arr]
            base = pow(p, g, MOD)
        else:
            base = p

        H = sum(arr)
        if H == 0:
            continue

        w = calc(base, arr, H)
        ans = (ans * w) % MOD
        if ans == 0:
            break

    print(ans)


