class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        if m == 0:
            return 0
        full = (1 << m) - 1
        size = full + 1

        lcms = [1] * size
        for mask in range(1, size):
            lsb = mask & -mask
            idx = lsb.bit_length() - 1
            prev = mask ^ lsb
            a = lcms[prev]
            b = target[idx]
            lcms[mask] = (a // gcd(a, b)) * b

        submasks = [[] for _ in range(size)]
        for mask in range(size):
            rem = full ^ mask
            sub = rem
            while sub:
                submasks[mask].append((sub, mask | sub))
                sub = (sub - 1) & rem

        INF = 10 ** 60
        dp = [INF] * size
        dp[0] = 0
        cost_cache = {}

        for x in nums:
            costs = cost_cache.get(x)
            if costs is None:
                costs = [0] * size
                for mask in range(1, size):
                    costs[mask] = (-x) % lcms[mask]
                cost_cache[x] = costs

            ndp = dp[:]
            for mask in range(size):
                base = dp[mask]
                if base == INF:
                    continue
                for sub, new_mask in submasks[mask]:
                    val = base + costs[sub]
                    if val < ndp[new_mask]:
                        ndp[new_mask] = val
            dp = ndp
            if dp[full] == 0:
                return 0

        return dp[full]

