MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    s = [ord(ch) - 97 for ch in S]
    size = 1 << N

    # Precompute transitions.
    # A state is a bitmask of length N:
    # bit i is 1 iff dp[i+1] - dp[i] == 1 in the LCS DP row.
    trans = []
    for mask in range(size):
        f = [0] * (N + 1)
        for i in range(1, N + 1):
            f[i] = f[i - 1] + ((mask >> (i - 1)) & 1)

        to_count = {}
        for c in range(26):
            prev = 0
            new_mask = 0

            for i in range(1, N + 1):
                best = f[i]
                if best < prev:
                    best = prev

                if s[i - 1] == c:
                    v = f[i - 1] + 1
                    if best < v:
                        best = v

                if best > prev:
                    new_mask |= 1 << (i - 1)

                prev = best

            to_count[new_mask] = to_count.get(new_mask, 0) + 1

        trans.append(list(to_count.items()))

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, cnt in enumerate(dp):
            if cnt:
                for nxt, mult in trans[mask]:
                    ndp[nxt] += cnt * mult
        dp = [x % MOD for x in ndp]

    ans = [0] * (N + 1)
    for mask, cnt in enumerate(dp):
        if cnt:
            ans[mask.bit_count()] = (ans[mask.bit_count()] + cnt) % MOD

    print(" ".join(map(str, ans)))

