import sys
from collections import deque

INF = 10**18

def bfs(src, adj):
    n = len(adj)
    dist = [-1] * n
    q = deque([src])
    dist[src] = 0
    while q:
        v = q.popleft()
        nd = dist[v] + 1
        for to, _ in adj[v]:
            if dist[to] == -1:
                dist[to] = nd
                q.append(to)
    return dist

def suurballe_vertex_disjoint(s, t, n, edges):
    # Split vertices: in = 2*v, out = 2*v+1
    # Find two internally vertex-disjoint paths from s to t.
    # Return their total length, or INF if impossible.
    if s == t:
        return INF

    N2 = 2 * n
    adj2 = [[] for _ in range(N2)]
    edge_list = []  # (u, v, cap, cost)

    def add_edge(u, v, cap, cost):
        idx = len(edge_list)
        edge_list.append((u, v, cap, cost))
        adj2[u].append((v, cost, idx))

    # vertex capacity edges
    for v in range(n):
        cap = 2 if (v == s or v == t) else 1
        add_edge(2 * v, 2 * v + 1, cap, 0)

    # original undirected edges become two directed edges
    for u, v in edges:
        add_edge(2 * u + 1, 2 * v, 2, 1)
        add_edge(2 * v + 1, 2 * u, 2, 1)

    source = 2 * s + 1
    target = 2 * t

    # First shortest path
    dist = [INF] * N2
    parent_edge = [-1] * N2
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heap.pop()
        if d != dist[u]:
            continue
        for v, c, eid in adj2[u]:
            if edge_list[eid][2] <= 0:
                continue
            nd = d + c
            if nd < dist[v]:
                dist[v] = nd
                parent_edge[v] = eid
                heap.append((nd, v))

    if dist[target] == INF:
        return INF

    on_path = [False] * len(edge_list)
    cur = target
    while cur != source:
        eid = parent_edge[cur]
        if eid == -1:
            return INF
        on_path[eid] = True
        u, v, cap, cost = edge_list[eid]
        cur = u

    # Free first adjacency
    del adj2

    # Build residual graph after sending one unit along the first path
    res = [[] for _ in range(N2)]
    for eid, (u, v, cap, cost) in enumerate(edge_list):
        if cap <= 0:
            continue
        if on_path[eid]:
            if cap - 1 > 0:
                res[u].append((v, cost))
            res[v].append((u, -cost))
        else:
            res[u].append((v, cost))

    # Potentials from first Dijkstra
    pot = [0 if d == INF else d for d in dist]

    # Second shortest path in residual graph
    dist2 = [INF] * N2
    dist2[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heap.pop()
        if d != dist2[u]:
            continue
        for v, c in res[u]:
            rc = c + pot[u] - pot[v]
            if rc < 0:
                rc = 0
            nd = d + rc
            if nd < dist2[v]:
                dist2[v] = nd
                heap.append((nd, v))

    if dist2[target] == INF:
        return INF

    return dist[target] + dist2[target]

def main():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    S -= 1
    T -= 1

    edges = []
    adj = [[] for _ in range(N)]
    for i in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        edges.append((u, v))
        adj[u].append((v, i))
        adj[v].append((u, i))

    # If the whole graph is a simple path, swapping is impossible.
    max_deg = max(len(a) for a in adj)
    if M == N - 1 and max_deg <= 2:
        print(-1)
        return

    dS = bfs(S, adj)
    dT = bfs(T, adj)

    ans = INF

    # ---------- Vertex gadget: a vertex of degree at least 3 ----------
    cntS = [0] * N
    firstS = [-1] * N
    cntT = [0] * N
    firstT = [-1] * N

    for v in range(N):
        if dS[v] > 0:
            c = 0
            f = -1
            for to, _ in adj[v]:
                if dS[to] == dS[v] - 1:
                    c += 1
                    f = to
                    if c >= 2:
                        break
            cntS[v] = c
            firstS[v] = f

        if dT[v] > 0:
            c = 0
            f = -1
            for to, _ in adj[v]:
                if dT[to] == dT[v] - 1:
                    c += 1
                    f = to
                    if c >= 2:
                        break
            cntT[v] = c
            firstT[v] = f

    for v in range(N):
        if len(adj[v]) < 3:
            continue
        if dS[v] == 0 or dT[v] == 0:
            extra = 4
        else:
            if cntS[v] == 1 and cntT[v] == 1 and firstS[v] == firstT[v]:
                extra = 4
            else:
                extra = 2
        cost = 2 * dS[v] + 2 * dT[v] + extra
        if cost < ans:
            ans = cost

    # ---------- Find bridges and 2-edge-connected components ----------
    sys.setrecursionlimit(1_000_000)
    tin = [-1] * N
    low = [-1] * N
    parent = [-1] * N
    parent_edge = [-1] * N
    is_bridge = [False] * M
    timer = 0

    # Iterative DFS for bridges
    stack = [(0, -1, 0)]
    while stack:
        v, p, state = stack.pop()
        if state == 0:
            tin[v] = low[v] = timer
            timer += 1
            stack.append((v, p, 1))
            for to, eid in adj[v]:
                if to == p:
                    continue
                if tin[to] == -1:
                    parent[to] = v
                    parent_edge[to] = eid
                    stack.append((to, v, 0))
                else:
                    low[v] = min(low[v], tin[to])
        else:
            for to, eid in adj[v]:
                if to == parent[v]:
                    continue
                if tin[to] == -1:
                    low[v] = min(low[v], low[to])
                    if low[to] > tin[v]:
                        is_bridge[eid] = True
                else:
                    low[v] = min(low[v], tin[to])

    comp_id = [-1] * N
    comps = []
    for i in range(N):
        if comp_id[i] != -1:
            continue
        cid = len(comps)
        q = deque([i])
        comp_id[i] = cid
        verts = []
        while q:
            v = q.popleft()
            verts.append(v)
            for to, eid in adj[v]:
                if is_bridge[eid]:
                    continue
                if comp_id[to] == -1:
                    comp_id[to] = cid
                    q.append(to)
        comps.append(verts)

    simple_cycle = [False] * len(comps)
    temp_deg = [0] * N

    # ---------- Simple cycle components ----------
    for cid, verts in enumerate(comps):
        if len(verts) <= 2:
            continue

        for v in verts:
            temp_deg[v] = 0

        for v in verts:
            for to, _ in adj[v]:
                if comp_id[to] == cid:
                    temp_deg[v] += 1

        ok = True
        for v in verts:
            if temp_deg[v] != 2:
                ok = False
                break
            temp_deg[v] = 0

        if not ok:
            continue

        simple_cycle[cid] = True
        L = len(verts)

        minS = INF
        cntSmin = 0
        uniqS = -1
        minT = INF
        cntTmin = 0
        uniqT = -1

        for v in verts:
            if dS[v] < minS:
                minS = dS[v]
                cntSmin = 1
                uniqS = v
            elif dS[v] == minS:
                cntSmin += 1
                uniqS = -1

            if dT[v] < minT:
                minT = dT[v]
                cntTmin = 1
                uniqT = v
            elif dT[v] == minT:
                cntTmin += 1
                uniqT = -1

        penalty = 1 if (cntSmin == 1 and cntTmin == 1 and uniqS == uniqT) else 0
        cost = L + 2 * minS + 2 * minT + penalty
        if cost < ans:
            ans = cost

    # ---------- If S and T are in the same non-simple 2-edge-connected component ----------
    if comp_id[S] == comp_id[T]:
        cid = comp_id[S]
        if not simple_cycle[cid]:
            val = suurballe_vertex_disjoint(S, T, N, edges)
            if val < ans:
                ans = val

    print(-1 if ans >= INF else ans)

if __name__ == "__main__":
    main()

