import sys
from bisect import bisect_left


def direct_dp(w, vals, cap):
    m = len(vals)
    prefix = [0] * (m + 1)
    s = 0
    for i, v in enumerate(vals, 1):
        s += v
        prefix[i] = s

    dp = [0] * (cap + 1)
    for c in range(cap + 1):
        k = c // w
        if k > m:
            k = m
        dp[c] = prefix[k]
    return dp


def apply_individual(dp, w, vals, cap):
    d = dp
    if w == 1:
        for a in vals:
            for c in range(cap, 0, -1):
                nv = d[c - 1] + a
                if nv > d[c]:
                    d[c] = nv
    else:
        for a in vals:
            for c in range(cap, w - 1, -1):
                nv = d[c - w] + a
                if nv > d[c]:
                    d[c] = nv
    return d


def apply_group_simple(dp, w, vals, cap):
    m = len(vals)
    prefix = [0] * (m + 1)
    s = 0
    for i, v in enumerate(vals, 1):
        s += v
        prefix[i] = s

    new = dp[:]
    old = dp
    kmax = min(m, cap // w)
    cap1 = cap + 1

    old_local = old
    new_local = new
    for k in range(1, kmax + 1):
        off = k * w
        pk = prefix[k]
        for c in range(off, cap1):
            nv = old_local[c - off] + pk
            if nv > new_local[c]:
                new_local[c] = nv
    return new


def build_dp(groups, sumc, X):
    if not groups:
        return [0]

    cap = X if sumc > X else sumc
    pruned = []

    for w, vals in groups.items():
        limit = cap // w
        if len(vals) > limit:
            vals.sort(reverse=True)
            vals = vals[:limit]
        else:
            vals.sort(reverse=True)
        if vals:
            pruned.append((w, vals))

    if not pruned:
        return [0] * (cap + 1)

    if len(pruned) == 1:
        w, vals = pruned[0]
        return direct_dp(w, vals, cap)

    costs = []
    for w, vals in pruned:
        if w > cap:
            costs.append(0)
            continue
        m = len(vals)
        ind = m * (cap - w + 1)
        if m == 1:
            costs.append(ind)
        else:
            kmax = min(m, cap // w)
            gc = cap + kmax * (cap + 1) - w * kmax * (kmax + 1) // 2
            costs.append(ind if ind < gc else gc)

    init = 0
    best = -1
    for i, cost in enumerate(costs):
        if cost > best:
            best = cost
            init = i

    w, vals = pruned[init]
    dp = direct_dp(w, vals, cap)

    for i, (w, vals) in enumerate(pruned):
        if i == init:
            continue
        if w > cap:
            continue

        m = len(vals)
        if m == 1:
            dp = apply_individual(dp, w, vals, cap)
        else:
            ind = m * (cap - w + 1)
            kmax = min(m, cap // w)
            gc = cap + kmax * (cap + 1) - w * kmax * (kmax + 1) // 2
            if gc < ind:
                dp = apply_group_simple(dp, w, vals, cap)
            else:
                dp = apply_individual(dp, w, vals, cap)

    mval = 0
    for c in range(cap + 1):
        if dp[c] < mval:
            dp[c] = mval
        else:
            mval = dp[c]
    return dp


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]

    if X < 3:
        print(0)
        return

    groups = [{}, {}, {}]
    sumc = [0, 0, 0]
    counts = [0, 0, 0]

    idx = 2
    for _ in range(N):
        v = data[idx]
        a = data[idx + 1]
        c = data[idx + 2]
        idx += 3

        t = v - 1
        sumc[t] += c
        counts[t] += 1

        d = groups[t]
        if c in d:
            d[c].append(a)
        else:
            d[c] = [a]

    if counts[0] == 0 or counts[1] == 0 or counts[2] == 0:
        print(0)
        return

    dps = [build_dp(groups[i], sumc[i], X) for i in range(3)]

    hi = min(dps[0][-1], dps[1][-1], dps[2][-1]) + 1
    lo = 0

    while hi - lo > 1:
        mid = (lo + hi) >> 1
        total = 0
        ok = True

        for dp in dps:
            pos = bisect_left(dp, mid)
            if pos == len(dp):
                ok = False
                break
            total += pos
            if total > X:
                ok = False
                break

        if ok:
            lo = mid
        else:
            hi = mid

    print(lo)


