import sys


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    mod = int(data[1])

    cap = N // 2
    K = N * (N - 1) // 2

    # Binomial coefficients modulo mod, up to K.
    C = [[1]]
    for i in range(1, K + 1):
        prev = C[-1]
        row = [1] * (i + 1)
        for j in range(1, i):
            v = prev[j - 1] + prev[j]
            if v >= mod:
                v -= mod
            row[j] = v
        C.append(row)

    # Transition factors in the basis (1+x)^k.
    # Adding a level of size s after a level of size a:
    # (1+x)^{C(s,2)} * sum_j (-1)^j C(s,j) (1+x)^{a(s-j)}
    trans = [[None] * (cap + 1) for _ in range(cap + 1)]
    max_shift = [[0] * (cap + 1) for _ in range(cap + 1)]
    for a in range(1, cap + 1):
        for s in range(1, cap + 1):
            base = s * (s - 1) // 2
            lst = []
            for j in range(s + 1):
                shift = base + a * (s - j)
                coeff = C[s][j]
                if j & 1:
                    coeff = mod - coeff
                    if coeff == mod:
                        coeff = 0
                lst.append((shift, coeff))
            trans[a][s] = lst
            max_shift[a][s] = base + a * s

    # choose[t][s] = C(N-t, s) mod mod
    choose = [[0] * (N + 1) for _ in range(N + 1)]
    for t in range(1, N):
        rem = N - t
        rowC = C[rem]
        for s in range(1, rem + 1):
            choose[t][s] = rowC[s]

    def new_table():
        return [[ [None] * (cap + 1) for _ in range(cap + 1) ] for _ in range(2)]

    # dp[t][last_parity][even_count][last_level_size] -> polynomial in basis (1+x)^k
    dp = [None] * (N + 1)
    dp[1] = new_table()
    dp[1][0][1][1] = [1]

    for t in range(1, N):
        table = dp[t]
        if table is None:
            continue

        rem_t = N - t
        minE = t - cap
        if minE < 0:
            minE = 0
        maxE = cap if cap < t else t

        for E in range(minE, maxE + 1):
            O = t - E
            for p in (0, 1):
                max_a = E if p == 0 else O
                if max_a <= 0:
                    continue

                table_p = table[p]
                rowE = table_p[E]

                for a in range(1, max_a + 1):
                    arr = rowE[a]
                    if arr is None:
                        continue
                    rowE[a] = None

                    arr = [v % mod for v in arr]
                    while len(arr) > 1 and arr[-1] == 0:
                        arr.pop()
                    if len(arr) == 1 and arr[0] == 0:
                        continue

                    L = len(arr)
                    np = p ^ 1

                    if np == 0:
                        limit = cap - E
                    else:
                        limit = cap - O
                    if limit <= 0:
                        continue
                    if limit > rem_t:
                        limit = rem_t

                    trans_a = trans[a]
                    ms_a = max_shift[a]

                    for s in range(1, limit + 1):
                        nt = t + s
                        new_E = E + (s if np == 0 else 0)

                        table_nt = dp[nt]
                        if table_nt is None:
                            table_nt = new_table()
                            dp[nt] = table_nt

                        row_nt = table_nt[np][new_E]
                        new_arr = row_nt[s]

                        terms = trans_a[s]
                        ms = ms_a[s]
                        needed = L + ms

                        if new_arr is None:
                            new_arr = [0] * needed
                            row_nt[s] = new_arr
                        elif len(new_arr) < needed:
                            new_arr.extend([0] * (needed - len(new_arr)))

                        ch = choose[t][s]
                        if ch == 0:
                            continue

                        ar = arr
                        na = new_arr

                        for sh, co in terms:
                            c = co * ch % mod
                            if c == 0:
                                continue

                            idx = sh
                            if c == 1:
                                for v in ar:
                                    na[idx] += v
                                    idx += 1
                            else:
                                for v in ar:
                                    na[idx] += v * c
                                    idx += 1

        dp[t] = None

    total = [0] * (K + 1)
    tableN = dp[N]
    if tableN is not None:
        E = cap
        O = N - E
        for p in (0, 1):
            max_a = E if p == 0 else O
            for a in range(1, max_a + 1):
                arr = tableN[p][E][a]
                if arr is None:
                    continue
                for i, v in enumerate(arr):
                    if v:
                        total[i] += v % mod

    for i in range(K + 1):
        total[i] %= mod

    start = N - 1
    ans = [0] * (K + 1)

    # Convert from basis (1+x)^k to ordinary coefficients.
    for k in range(start, K + 1):
        ck = total[k]
        if ck:
            row = C[k]
            for m in range(start, k + 1):
                ans[m] += ck * row[m]

    out = [str(ans[m] % mod) for m in range(start, K + 1)]
    sys.stdout.write(" ".join(out) + "\n")


