    main()

import sys
import math


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    M = data[1]
    P = data[2:2 + N]

    if N == 1:
        print(math.isqrt(M // P[0]))
        return

    pmin = min(P)
    if M < pmin:
        print(0)
        return
    if M < 2 * pmin:
        print(1)
        return

    sumP = sum(P)
    P.sort()
    maxP = P[-1]

    # Safe infeasible upper bounds for the marginal-cost threshold.
    x = math.isqrt(M // pmin) + 1
    high1 = pmin * (2 * x - 1)

    q = math.isqrt(M // sumP) + 1
    high2 = maxP * (2 * q - 1)

    high = high1 if high1 < high2 else high2
    low = 0

    def cost(t, Ps=P, M=M, maxP=maxP, limit=M + 1):
        s = 0
        if t >= maxP:
            for p in Ps:
                c = (t // p + 1) >> 1
                s += p * c * c
                if s > M:
                    return limit
        else:
            for p in Ps:
                if p > t:
                    break
                c = (t // p + 1) >> 1
                s += p * c * c
                if s > M:
                    return limit
        return s

    # Heuristic bracketing around the continuous estimate.
    if high > 1:
        A = 0.0
        for p in P:
            A += 1.0 / p

        est = 2.0 * math.sqrt(M / A)
        h = int(est * 2.0 + 10.0)
        if h < 1:
            h = 1

        if h < high:
            if cost(h) > M:
                high = h
            else:
                low = h
                for _ in range(5):
                    if low * 2 >= high:
                        break
                    h2 = low * 2
                    if cost(h2) > M:
                        high = h2
                        break
                    low = h2

    # Binary search the largest T with total cost of all marginal costs <= T at most M.
    while high - low > 1:
        mid = (low + high) >> 1
        if cost(mid) <= M:
            low = mid
        else:
            high = mid

    T = low

    s = 0
    cnt = 0
    if T >= maxP:
        for p in P:
            c = (T // p + 1) >> 1
            cnt += c
            s += p * c * c
    else:
        for p in P:
            if p > T:
                break
            c = (T // p + 1) >> 1
            cnt += c
            s += p * c * c

    ans = cnt + (M - s) // (T + 1)
    print(ans)


