import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, A, B = data[:4]
    full_mask = (1 << B) - 1
    low_mask = (1 << (B - A + 1)) - 1
    msb = 1 << (B - 1)

    base = [0] * B
    for j in range(B - 1):
        base[j] = 1 << (j + 1)
    base[B - 1] = low_mask
    base = tuple(base)

    def compose(t1, t2):
        res = [0] * B
        for j in range(B):
            m = t2[j]
            u = 0
            while m:
                lsb = m & -m
                u |= t1[lsb.bit_length() - 1]
                m ^= lsb
            res[j] = u
        return tuple(res)

    max_pow = max(1, N.bit_length() + 1)
    powers = [base]
    for _ in range(1, max_pow):
        powers.append(compose(powers[-1], powers[-1]))

    def apply_good(state, k, powers=powers, full_mask=full_mask):
        if state == 0:
            return 0
        if state == full_mask:
            return full_mask
        p = 0
        while k:
            if k & 1:
                t = powers[p]
                res = 0
                bit = 1
                for mask in t:
                    if state & mask:
                        res |= bit
                    bit <<= 1
                state = res
                if state == 0:
                    return 0
                if state == full_mask:
                    return full_mask
            k >>= 1
            p += 1
        return state

    state = msb
    pos = 1
    idx = 4
    for _ in range(M):
        if state == 0:
            break
        L = data[idx]
        R = data[idx + 1]
        idx += 2
        good = L - pos - 1
        if good > 0:
            if state != full_mask:
                if good <= B:
                    for __ in range(good):
                        if state & low_mask:
                            state = (state >> 1) | msb
                        else:
                            state >>= 1
                        if state == 0:
                            break
                        if state == full_mask:
                            break
                else:
                    state = apply_good(state, good)
            if state == 0:
                break
        bad = R - L + 1
        if bad >= B:
            state = 0
            break
        else:
            state >>= bad
        pos = R

    if state == 0:
        sys.stdout.write("No\n")
        return
    good = N - pos
    if good > 0 and state != full_mask:
        if good <= B:
            for __ in range(good):
                if state & low_mask:
                    state = (state >> 1) | msb
                else:
                    state >>= 1
                if state == 0:
                    break
                if state == full_mask:
                    break
        else:
            state = apply_good(state, good)
    if state & msb:
        sys.stdout.write("Yes\n")
    else:
        sys.stdout.write("No\n")

if __name__ == "__main__":
    solve()

