class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        arr = [1 if c == '1' else 0 for c in s]

        runs = []
        cur = 1
        for i in range(1, n):
            if arr[i] == arr[i - 1]:
                cur += 1
            else:
                runs.append(cur)
                cur = 1
        runs.append(cur)

        max_run = max(runs)
        if numOps == 0 or max_run == 1:
            return max_run

        def can(L: int) -> bool:
            if L == 1:
                # Minimum flips to make the string alternating.
                cost = 0
                # Pattern: 0, 1, 0, 1, ...
                for i, a in enumerate(arr):
                    if a != (i & 1):
                        cost += 1
                # The other alternating pattern is its complement.
                return min(cost, n - cost) <= numOps

            # For L >= 2, each original run of length x needs exactly
            # x // (L + 1) flips to be broken into pieces of length <= L.
            div = L + 1
            needed = 0
            for length in runs:
                needed += length // div
                if needed > numOps:
                    return False
            return True

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

from typing import List

class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        MOD = 1_000_000_007
        n = len(nums)

        c2 = [0] * (n + 1)
        for i in range(2, n + 1):
            c2[i] = i * (i - 1) // 2

        def choose(m: int, k: int) -> int:
            if k == 0:
                return 1
            if k == 1:
                return m
            if k == 2:
                return c2[m] if m >= 2 else 0
            return 0

        right = {}
        for v in nums:
            right[v] = right.get(v, 0) + 1

        same_right = 0
        for f in right.values():
            same_right += f * (f - 1) // 2

        left = {}
        same_left = 0
        ans = 0

        for i, x in enumerate(nums):
            f = right[x]
            same_right -= f - 1
            right[x] = f - 1

            if 2 <= i <= n - 3:
                Lx = left.get(x, 0)
                Rx = right.get(x, 0)
                Lnon = i - Lx
                Rnon = (n - 1 - i) - Rx

                # Number of pairs with distinct values among non-x elements.
                D_L = c2[Lnon] - (same_left - c2[Lx])
                D_R = c2[Rnon] - (same_right - c2[Rx])

                total = 0

                # Middle value appears at least 3 times total:
                # at least 2 of the 4 side elements are x.
                for a in range(3):
                    for b in range(3):
                        if a + b >= 2:
                            total += (
                                choose(Lx, a) * choose(Lnon, 2 - a) *
                                choose(Rx, b) * choose(Rnon, 2 - b)
                            )

                # Middle value appears exactly 2 times total:
                # the other 3 side elements must be pairwise distinct.
                if Lx or Rx:
                    A = 0
                    B = 0

                    for v, lf in left.items():
                        if v == x:
                            continue
                        rf = right.get(v, 0)
                        if rf:
                            A += lf * rf * (Rnon - rf)
                            B += lf * rf * (Lnon - lf)

                    if Lx:
                        total += Lx * (Lnon * D_R - A)
                    if Rx:
                        total += Rx * (Rnon * D_L - B)

                ans = (ans + total) % MOD

            lf = left.get(x, 0)
            same_left += lf
            left[x] = lf + 1

        return ans

