from collections import defaultdict

def count_and_mark(intervals, groups, coord, covered):
    total = 0
    for key, ivs in intervals.items():
        idxs = groups.get(key)
        if not idxs:
            continue
        idxs.sort(key=coord.__getitem__)
        vals = [coord[i] for i in idxs]
        ivs.sort()
        p = 0
        n = len(vals)
        cur_l, cur_r = ivs[0]
        for l, r in ivs[1:]:
            if l <= cur_r + 1:
                if r > cur_r:
                    cur_r = r
                continue
            while p < n and vals[p] < cur_l:
                p += 1
            while p < n and vals[p] <= cur_r:
                covered[idxs[p]] = 1
                total += 1
                p += 1
            cur_l, cur_r = l, r
        while p < n and vals[p] < cur_l:
            p += 1
        while p < n and vals[p] <= cur_r:
            covered[idxs[p]] = 1
            total += 1
            p += 1
    return total

def main():
    input = sys.stdin.buffer.readline
    N, M, x, y = map(int, input().split())
    hx = [0] * N
    hy = [0] * N
    for i in range(N):
        xi, yi = map(int, input().split())
        hx[i] = xi
        hy[i] = yi

    h_intervals = defaultdict(list)
    v_intervals = defaultdict(list)

    for _ in range(M):
        d, c_token = input().split()
        c = int(c_token)
        if d == b'U':
            old = y
            y += c
            v_intervals[x].append((old, y) if old <= y else (y, old))
        elif d == b'D':
            old = y
            y -= c
            v_intervals[x].append((old, y) if old <= y else (y, old))
        elif d == b'L':
            old = x
            x -= c
            h_intervals[y].append((old, x) if old <= x else (x, old))
        else:  # b'R'
            old = x
            x += c
            h_intervals[y].append((old, x) if old <= x else (x, old))

    h_covered = bytearray(N)
    v_covered = bytearray(N)

    if h_intervals:
        by_y = {}
        # Only houses whose y has at least one horizontal segment can be counted.
        for i in range(N):
            yi = hy[i]
            if yi in h_intervals:
                by_y.setdefault(yi, []).append(i)
        H = count_and_mark(h_intervals, by_y, hx, h_covered)
        del by_y, h_intervals
    else:
        H = 0

    if v_intervals:
        by_x = {}
        for i in range(N):
            xi = hx[i]
            if xi in v_intervals:
                by_x.setdefault(xi, []).append(i)
        V = count_and_mark(v_intervals, by_x, hy, v_covered)
        del by_x, v_intervals
    else:
        V = 0

    if H and V:
        both = 0
        h = h_covered
        v = v_covered
        for i in range(N):
            if h[i] and v[i]:
                both += 1
    else:
        both = 0

    sys.stdout.write(f"{x} {y} {H + V - both}\n")

