from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        present = [False] * (T + 1)
        vals = []
        isolated = 0

        for x in nums:
            if x <= T:
                if not present[x]:
                    present[x] = True
                    vals.append(x)
            else:
                isolated += 1

        if len(vals) <= 1:
            return len(vals) + isolated

        if T >= 1 and present[1]:
            return 1 + isolated

        parent = list(range(T + 1))
        size = [1] * (T + 1)
        components = len(vals)
        rep = [0] * (T + 1)
        limit = T + 1

        for a in vals:
            for m in range(a, limit, a):
                r = rep[m]
                if r == 0:
                    rep[m] = a
                else:
                    x = a
                    while parent[x] != x:
                        parent[x] = parent[parent[x]]
                        x = parent[x]
                    ra = x

                    x = r
                    while parent[x] != x:
                        parent[x] = parent[parent[x]]
                        x = parent[x]
                    rb = x

                    if ra != rb:
                        if size[ra] < size[rb]:
                            ra, rb = rb, ra
                        parent[rb] = ra
                        size[ra] += size[rb]
                        components -= 1
                        if components == 1:
                            return 1 + isolated

        return components + isolated
